from typing import TypeVar, Generic

T = TypeVar("T")


class Stack(Generic[T]):
    """A last-in, first-out (LIFO) stack implementation."""

    def __init__(self) -> None:
        """Initialize an empty stack."""
        self._items: list[T] = []

    def push(self, item: T) -> None:
        """Add an item to the top of the stack."""
        self._items.append(item)

    def pop(self) -> T:
        """Remove and return the top item of the stack.

        Raises:
            IndexError: If the stack is empty.
        """
        if self.is_empty():
            raise IndexError("pop from empty stack")
        return self._items.pop()

    def peek(self) -> T:
        """Return the top item of the stack without removing it.

        Raises:
            IndexError: If the stack is empty.
        """
        if self.is_empty():
            raise IndexError("peek from empty stack")
        return self._items[-1]

    def is_empty(self) -> bool:
        """Return True if the stack is empty, otherwise False."""
        return len(self._items) == 0

    def __len__(self) -> int:
        """Return the number of items in the stack."""
        return len(self._items)

/**
 * Creates a debounced function that delays invoking `func` until after `delay`
 * milliseconds have elapsed since the last time the debounced function was called.
 *
 * @template {(...args: any[]) => any} T
 * @param {T} func - The function to debounce.
 * @param {number} delay - The delay in milliseconds.
 * @returns {(...args: Parameters<T>) => void} The new debounced function.
 */
function debounce(func, delay) {
  let timeoutId;

  return function (...args) {
    clearTimeout(timeoutId);

    timeoutId = setTimeout(() => {
      func.apply(this, args);
    }, delay);
  };
}

from typing import Any


def parse_json(s: str) -> Any:
    """Parse a JSON string into a Python object.

    Supports null, true, false, numbers, strings, arrays, and objects.
    Raises ValueError if the input is not valid JSON.

    This implementation does not use the standard library json module.
    """
    parser = _Parser(s)
    value = parser.parse_value()
    parser.skip_ws()
    if parser.i != parser.n:
        raise ValueError("extra data after JSON value")
    return value


class _Parser:
    __slots__ = ("s", "i", "n")

    def __init__(self, s: str) -> None:
        self.s = s
        self.i = 0
        self.n = len(s)

    def parse_value(self) -> Any:
        self.skip_ws()
        if not self._has_more():
            raise ValueError("unexpected end of input")

        ch = self.s[self.i]
        if ch == "n":
            return self._parse_literal("null", None)
        if ch == "t":
            return self._parse_literal("true", True)
        if ch == "f":
            return self._parse_literal("false", False)
        if ch == '"':
            return self._parse_string()
        if ch == "[":
            return self._parse_array()
        if ch == "{":
            return self._parse_object()
        if ch == "-" or ("0" <= ch <= "9"):
            return self._parse_number()
        raise ValueError(f"unexpected character {ch!r}")

    def skip_ws(self) -> None:
        while self._has_more() and self.s[self.i] in " \t\n\r":
            self.i += 1

    def _has_more(self) -> bool:
        return self.i < self.n

    def _peek(self) -> str:
        if not self._has_more():
            raise ValueError("unexpected end of input")
        return self.s[self.i]

    def _expect(self, expected: str) -> None:
        if not self._has_more() or self.s[self.i] != expected:
            raise ValueError(f"expected {expected!r}")
        self.i += 1

    def _parse_literal(self, literal: str, value: Any) -> Any:
        end = self.i + len(literal)
        if end > self.n or self.s[self.i:end] != literal:
            raise ValueError(f"expected {literal!r}")
        self.i = end
        return value

    def _parse_number(self) -> Any:
        start = self.i
        if self._peek() == "-":
            self.i += 1

        if not self._has_more():
            raise ValueError("invalid number")

        first = self.s[self.i]
        if first == "0":
            self.i += 1
        elif "1" <= first <= "9":
            self.i += 1
            while self._has_more() and "0" <= self.s[self.i] <= "9":
                self.i += 1
        else:
            raise ValueError("invalid number")

        is_float = False
        if self._has_more() and self.s[self.i] == ".":
            is_float = True
            self.i += 1
            if not self._has_more() or not ("0" <= self.s[self.i] <= "9"):
                raise ValueError("invalid number")
            while self._has_more() and "0" <= self.s[self.i] <= "9":
                self.i += 1

        if self._has_more() and self.s[self.i] in "eE":
            is_float = True
            self.i += 1
            if self._has_more() and self.s[self.i] in "+-":
                self.i += 1
            if not self._has_more() or not ("0" <= self.s[self.i] <= "9"):
                raise ValueError("invalid number")
            while self._has_more() and "0" <= self.s[self.i] <= "9":
                self.i += 1

        num_str = self.s[start:self.i]
        if is_float:
            return float(num_str)
        return int(num_str)

    def _parse_string(self) -> str:
        self._expect('"')
        chars = []
        while self._has_more():
            ch = self.s[self.i]
            if ch == '"':
                self.i += 1
                return "".join(chars)
            if ch == "\\":
                self.i += 1
                if not self._has_more():
                    raise ValueError("invalid escape")
                esc = self.s[self.i]
                if esc == '"':
                    chars.append('"')
                elif esc == "\\":
                    chars.append("\\")
                elif esc == "/":
                    chars.append("/")
                elif esc == "b":
                    chars.append("\b")
                elif esc == "f":
                    chars.append("\f")
                elif esc == "n":
                    chars.append("\n")
                elif esc == "r":
                    chars.append("\r")
                elif esc == "t":
                    chars.append("\t")
                elif esc == "u":
                    self.i += 1
                    if self.i + 4 > self.n:
                        raise ValueError("invalid unicode escape")
                    hex_str = self.s[self.i : self.i + 4]
                    try:
                        code = int(hex_str, 16)
                    except ValueError:
                        raise ValueError("invalid unicode escape")
                    chars.append(chr(code))
                    self.i += 4
                    continue
                else:
                    raise ValueError(f"invalid escape {esc!r}")
                self.i += 1
            else:
                if ord(ch) < 0x20:
                    raise ValueError("unescaped control character")
                chars.append(ch)
                self.i += 1
        raise ValueError("unterminated string")

    def _parse_array(self) -> list:
        self._expect("[")
        self.skip_ws()
        if self._peek() == "]":
            self.i += 1
            return []

        values = []
        while True:
            values.append(self.parse_value())
            self.skip_ws()
            ch = self._peek()
            if ch == ",":
                self.i += 1
                self.skip_ws()
                if self._peek() == "]":
                    raise ValueError("trailing comma in array")
                continue
            if ch == "]":
                self.i += 1
                return values
            raise ValueError("expected ',' or ']' in array")

    def _parse_object(self) -> dict:
        self._expect("{")
        self.skip_ws()
        if self._peek() == "}":
            self.i += 1
            return {}

        obj = {}
        while True:
            self.skip_ws()
            if self._peek() != '"':
                raise ValueError("expected string key")
            key = self._parse_string()
            self.skip_ws()
            self._expect(":")
            value = self.parse_value()
            obj[key] = value
            self.skip_ws()
            ch = self._peek()
            if ch == ",":
                self.i += 1
                self.skip_ws()
                if self._peek() == "}":
                    raise ValueError("trailing comma in object")
                continue
            if ch == "}":
                self.i += 1
                return obj
            raise ValueError("expected ',' or '}' in object")
